def expected_calibration_error(prob, y, n_bins=10):
    bins = np.linspace(0, 1, n_bins + 1)
    idx = np.digitize(prob, bins[1:-1])
    ece = 0.0
    for b in range(n_bins):
        mask = idx == b
        if mask.sum() == 0:
            continue
        conf = prob[mask].mean()
        acc = y[mask].mean()
        ece += mask.sum() / len(prob) * abs(conf - acc)
    return float(ece)

def calibration_report(prob_raw, prob_cal, y):
    return {
        "ece_raw": expected_calibration_error(prob_raw, y),
        "ece_calibrated": expected_calibration_error(prob_cal, y),
    }
```
ECE summarizes the gap between confidence and accuracy across bins.

