import numpy as np

def gini(values):
    v = np.sort(np.asarray(values, dtype=float))
    n = len(v)
    if n == 0 or v.sum() == 0:
        return 0.0
    cum = np.cumsum(v)
    return (n + 1 - 2 * cum.sum() / cum[-1]) / n

def gini_per_category(df, value="revenue", group="category"):
    return df.groupby(group)[value].apply(gini).rename("gini")
