import numpy as np

class BalancedBatchSampler:
    def __init__(self, y, batch_size=64, seed=0):
        self.batch_size = batch_size
        self.classes = np.unique(y)
        self.idx_per_class = {c: np.where(y == c)[0] for c in self.classes}
        self.rng = np.random.default_rng(seed)

    def __iter__(self):
        per_class = self.batch_size // len(self.classes)
        while True:
            batch = []
            for c in self.classes:
                pool = self.idx_per_class[c]
                batch.extend(self.rng.choice(pool, size=per_class, replace=True))
            yield np.array(batch)
```
Sampling with replacement from minority classes lets you train indefinitely without exhausting them.

