class TorchBalancedSampler(Sampler):
    def __init__(self, y, batch_size=64, n_batches=1000, seed=0):
        self.inner = BalancedBatchSampler(y, batch_size, seed)
        self.n_batches = n_batches

    def __iter__(self):
        for i, b in enumerate(self.inner):
