def lagged_corr(x, y, max_lag=10):
    out = {}
    for lag in range(-max_lag, max_lag + 1):
        if lag < 0:
            a, b = x[-lag:], y[:lag]
        elif lag > 0:
            a, b = x[:-lag], y[lag:]
        else:
            a, b = x, y
        out[lag] = float(np.corrcoef(a, b)[0, 1])
