def per_group_slopes_vec(df, group_col, x, y):
    g = df.groupby(group_col)
    mean_x = g[x].transform("mean")
    mean_y = g[y].transform("mean")
    cov = ((df[x] - mean_x) * (df[y] - mean_y)).groupby(df[group_col]).sum()
    var = ((df[x] - mean_x) ** 2).groupby(df[group_col]).sum()
    return (cov / var).rename("slope")
```
